function universePage(){let world='';if(globalThis.RapWorld){const rivals=globalThis.RapWorld.standings(s);world=`<div class="section-heading"><h2>Mientras tú decides, la escena se mueve</h2><small>Artistas ficticios · S${s.week}</small></div><div class="table-wrap"><table><thead><tr><th>Artista</th><th>Mercado</th><th>Streams / día</th><th>Fans activos</th><th>YouTube</th><th>Estado</th></tr></thead><tbody><tr><td><strong>${esc(s.player.name)} · Tú</strong></td><td>${esc(s.career.marketId||'Colombia')}</td><td>${compact((s.stats.lastWeekStreams||0)/7)}</td><td>${compact(s.player.fans)}</td><td>${compact(s.youtube?.subscribers||0)}</td><td>Construyendo carrera</td></tr>${rivals.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${esc(r.market)}</td><td>${compact(r.dailyStreams)}</td><td>${compact(r.activeFans)}</td><td>${compact(r.youtubeSubscribers)}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div><p class="note">Estos personajes tienen sus propios lanzamientos, giras, descansos y altibajos. Sus estadísticas iniciales pertenecen al mundo ficticio. Los artistas reales aparecen después como referencias observadas.</p>`;}return industryLinks()+world+baseUniversePage();}
