function campaignModal(){const films=E.ppvMarketingSummary?.(s)?.films||s.ppvFilms||[],shows=s.ppvShows||[],ready=s.projects.filter(p=>p.type==='deluxe'&&p.status==='ready');modal('Películas y campañas PPV',`<p>Elige una película existente o crea una con un concierto grabado. Puedes mantener campañas simultáneas. El presupuesto se ejecuta por semanas y no garantiza recuperar la inversión.</p><form data-form="campaign"><label class="field">Película<select name="filmId"><option value="new">Crear nueva película</option>${films.map(f=>`<option value="${esc(f.id)}">Promocionar · ${esc(f.name)} · ${money(f.price)}</option>`).join('')}</select></label><label class="field">Concierto para una película nueva<select name="showId">${shows.slice().reverse().map(show=>`<option value="${esc(show.id)}">S${show.week} · ${esc(show.venue)} · ${fmt(show.attendance)} asistentes</option>`).join('')||'<option value="">Sin concierto disponible</option>'}</select></label><label class="field">Nombre de nueva película<input name="name" maxlength="100" value="Mi concierto en vivo"></label><div class="form-grid"><label class="field">Precio de acceso para película nueva<input name="price" type="number" min="0.01" step="0.01" value="49" required></label><label class="field">Presupuesto total de medios<input name="budget" type="number" min="0" step="0.01" value="1000" required></label><label class="field">Semanas de publicidad<input name="duration" type="number" min="1" step="1" value="12" required></label><label class="field">Mercado de difusión<select name="scope"><option value="country">País de origen</option><option value="latam" selected>LATAM</option><option value="usa"${s.progression?.usaUnlocked?'':' disabled'}>USA${s.progression?.usaUnlocked?'':' · requiere superar difícil'}</option></select></label><label class="field">Deluxe opcional<select name="deluxeProjectId"><option value="">Sin deluxe</option>${ready.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · distribución $700</option>`).join('')}</select></label></div><div class="album-order-quote" data-ppv-quote aria-live="polite"></div><p class="note">Las películas existentes conservan su precio y derechos. Los medios y el servicio de compra de publicidad se muestran por separado. No se cobra por consultar esta cotización.</p><div class="form-actions">${btn('Volver','type="button" data-ui="close"','outline')}${btn('Autorizar campaña','type="submit"')}</div></form>`);}
function syncPpvQuote(form){
 if(!form?.querySelector||!E.ppvCampaignQuote)return;const data=Object.fromEntries(new FormData(form)),payload={id:'ppv',mode:data.filmId==='new'?'create':'existing',filmId:data.filmId==='new'?undefined:data.filmId,showId:data.showId||undefined,name:data.name,price:Number(data.price),budget:Number(data.budget),duration:Number(data.duration),scope:data.scope||'latam',deluxeProjectId:data.deluxeProjectId||undefined},q=E.ppvCampaignQuote(s,payload),host=form.querySelector('[data-ppv-quote]');if(host)host.innerHTML=line('Medios por semana',money(q.weeklyBudget||0))+line('Servicio de operación',fmt((q.coordinationRate??q.operationRate??0)*100,2)+'%')+line('Salida semanal prevista',money(q.weeklyTotal||0))+line('Caja libre hoy',money(q.spendable||0))+((q.weeklyTotal||0)+(q.deluxeCost||0)>(q.spendable||0)?'<p class="album-quote-error">La caja actual no cubre toda esa previsión. Se ejecutará solo publicidad financiada, compartiendo los fondos libres entre campañas; no se crea deuda para completarla.</p>':'')+(q.errors||[]).map(x=>'<p class="album-quote-error">'+esc(x)+'</p>').join('');const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=!q.ok;
}
function syncCampaignFields(form){
 if(!form?.querySelector)return;
 const select=form.querySelector('select[name="filmId"]');if(!select)return;
 const existing=select.value!=='new';
 for(const name of ['showId','name','price']){const input=form.querySelector('[name="'+name+'"]');if(input)input.disabled=existing;}
 let note=form.querySelector('[data-campaign-mode-note]');
 if(!note){note=document.createElement('p');note.className='note';note.dataset.campaignModeNote='';note.setAttribute('role','status');select.closest('label')?.after(note);}
 note.textContent=existing?'Se usará la película elegida con su concierto, nombre y precio anteriores. Los campos de película nueva están desactivados.':'Define los datos de la nueva película; se conservarán si cambias de opción.';
}
function advanceModal(){
 if(hold()){toast('Esta carrera requiere conciliar su estado antes de simular.');return;}
 const f=E.weeklyForecast(s);
 const preview=clockTarget(),routine=advanceRun?.routine;
 modal('Comenzar la semana '+s.week,`<p><strong>${startMode==='day'?'Avance manual: un día':esc(periodLabels[clockOptions.period])+(preview.ok&&preview.targetDate?' · hasta '+esc(clockDate(preview.targetDate)):'')}</strong></p>${startMode!=='day'?'<p>'+ (clockOptions.repeat?'Rutina autorizada: '+(routine?.items||[]).map(x=>esc(x.label)).join(', '):'No se repetirán actividades en semanas posteriores.')+'</p>':''}${routine?.excluded?.length?'<p class="note">Solo esta semana: '+routine.excluded.map(x=>esc(x.label)).join(', ')+'.</p>':''}<p>${s.plan.length?'Estas son tus decisiones para la semana. Cada sesión se ejecuta en su día.':'No has programado acciones. El catálogo y los gastos seguirán su curso.'}</p>${s.plan.map((p,i)=>`<div class="finance-line"><span><small>${['Lunes','Miércoles','Viernes'][i]}</small>${esc(actionName(p))}</span><b>${money(p.cost??0)}</b></div>`).join('')}${line('Salidas previstas',money(f.totalCosts),'Incluye gastos semanales; los ingresos futuros son inciertos','total')}${f.clientCosts?line('Presupuesto de tus artistas',money(f.clientCosts),'Se paga desde sus cuentas; no está incluido en tus salidas personales'):''}${f.mediaPlan?.label?line('Publicidad prevista del sello',money(f.mediaPlan.label),'Se ejecuta desde la caja segregada del sello; no está en tus salidas personales'):''}${f.labelSettlementDue?line('Liquidación prevista para el sello',money(f.labelSettlementDue),'Se cobra en su cuenta separada'):''}${line('Consumo neto de energía programado',fmt(f.energy),'Las acciones de descanso pueden reducir este consumo')}${line('Energía estimada tras recuperación semanal',fmt(f.endingEnergy)+'/100','Incluye hasta 22 puntos de recuperación al cierre')}<p class="note">La agenda queda fijada hasta el domingo. Cada día actualiza las ventas; el cierre semanal aplica gastos y obligaciones. 1× = un día cada 5 segundos. El reloj seguirá hasta la meta elegida. Sin repetición de rutina, las semanas siguientes quedan sin actividades. Las decisiones puntuales requieren tu intervención; cerrar el juego no genera avance.</p><div class="form-actions">${btn('Seguir planificando','data-ui="close"','outline')}${btn(startMode==='day'?'Comenzar y avanzar un día':'Comenzar S'+s.week,'data-ui="resolve"','btn copper')}</div>`);
}
function resolve(){if(s.calendar?.status==='running'){closeModal();toast('La semana ya está en marcha. Usa los controles del reloj para continuar.');return;}const scrollX=window.scrollX||0,scrollY=window.scrollY||0,r=E.startWeek(s);if(!r?.ok){toast(r?.message||'No se pudo comenzar.');return;}closeModal();refreshAdvanceTotals();const stored=persist();render();window.scrollTo(scrollX,scrollY);if(!stored){toast('El avance permanece en pausa porque no se pudo guardar.');return;}if(startMode==='day')advanceOneDay(true);else{if(advanceRun)advanceRun.reason=null;simClock.play();}}
function showWeekReport(oldWeek,r){const report=r||{},lines=[...(report.highlights||[]),...(report.messages||report.lines||report.actions||[]).map(l=>typeof l==='string'?reportActionText(l):{...l,text:reportActionText(l.text||l.message||l.label||l.name||'')}),...(report.shows||[]).map(v=>(v.venue||v.name||'Concierto')+': '+fmt(v.attendance)+' asistentes · resultado '+money(v.net??v.estimatedNet??v.profit??0))];modal('Así terminó S'+oldWeek,`<p>Ya estás en S${s.week}. Estas consecuencias quedan guardadas en tu carrera.</p><div class="metrics" style="grid-template-columns:1fr 1fr">${metric('Caja personal al cierre',money(s.cash),'Cuenta personal')}${s.label?metric('Caja del sello al cierre',money(s.label.cash),'Cuenta segregada'):''}${metric('Resultado de caja',money(s.stats?.lastWeekNet??0),'Entradas menos salidas externas; personal y sello, sin traslados internos')}</div>${E.taxSummary?.(s)?.totalDebt?line('Impuestos pendientes',money(E.taxSummary(s).totalDebt),'Revisa la factura en Patrimonio'):''}${line('Streams de la semana',fmt(s.stats?.lastWeekStreams??0))}${line('Comunidad activa',fmt(s.player.fans))}${line('Ingresos de caja',money(s.stats?.lastWeekIncome??0))}${line('Nuevos ingresos devengados',money(report.accrued??0),'Todavía pueden estar pendientes de liquidación')}${line('Liquidaciones cobradas',money(report.settled??0))}${line('Pendiente de cobrar',money(report.pending??s.stats?.revenuePending??0))}${line('Salidas de caja',money(s.stats?.lastWeekExpenses??0))}${lines.slice(0,16).map(l=>`<div class="report-line">${esc(typeof l==='string'?l:l.text||l.message||l.label||l.name||'')}</div>`).join('')}<div class="section-gap">${renderEvents()}</div><div class="form-actions">${btn('Ver charts','data-nav="charts"','outline')}${btn('Ver regalías','data-nav="royalties"','outline')}${btn('Ver movimientos','data-ui="report-ledger"','outline')}${btn('Planificar S'+s.week,'data-ui="close"')}</div>`);}
