 if(el.dataset.wealthJump){const target=document.getElementById(el.dataset.wealthJump);if(target){const quicknav=document.querySelector('.patrimony-quicknav');if(quicknav)quicknav.open=false;if(el.dataset.wealthJump==='wealth-summary')window.scrollTo(0,0);else{for(let parent=target.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;const offset=($('#simulation-clock')?.offsetHeight||0)+16;window.scrollTo(0,Math.max(0,window.scrollY+target.getBoundingClientRect().top-offset));target.focus({preventScroll:true});}}return;}
